//44de00 placement, unit overlap and exact terrain writes.96-structure probe is a boundary.
import ghidra.app.emulator.EmulatorHelper;
import java.io.PrintWriter;
public class ZNativeWreckPlacementOracle extends ZNativeWorldEffectOracle{
 static final long P=O+0x600,H=O+0x400,U=0x5e30c8;int eh,events,probe;
 void event(int...vs){events++;for(int v:vs)eh=(eh^v)*16777619;}
 void execute(EmulatorHelper e)throws Exception{eh=0x811c9dc5;events=0;e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",O);e.writeRegister("EDX",P);e.setBreakpoint(toAddr(RET));if(!e.run(toAddr(0x44de00),null,monitor))throw new Exception(e.getLastError());while(e.readRegister("EIP").longValue()!=RET){long pc=e.readRegister("EIP").longValue(),sp=e.readRegister("ESP").longValue();if(pc==0x44dd70){event(0,(short)e.readRegister("ECX").intValue(),(short)e.readRegister("EDX").intValue());e.writeRegister("EAX",probe);}else if(pc==0x41eb90)event(1,(short)e.readRegister("ECX").intValue(),(short)e.readRegister("EDX").intValue(),(int)read(e,sp+4,4),(int)read(e,0x4d02a2,1));else throw new Exception("Unexpected "+Long.toHexString(pc));long r=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(r),null,monitor))throw new Exception(e.getLastError());}}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){EmulatorHelper e=new EmulatorHelper(currentProgram);try{for(long a:new long[]{0x44dd70,0x41eb90})e.setBreakpoint(toAddr(a));int[]codes={0,7,8,10,23,24,28,35,60,68,127};int[]delta={-65,-33,-17,-16,-1,0,16,17,32,33,65};for(int s=0;s<2048;s++){probe=s>>3&1;e.writeMemory(toAddr(O),new byte[192]);e.writeMemory(toAddr(H),new byte[64]);e.writeMemory(toAddr(P),new byte[44]);e.writeMemory(toAddr(U),new byte[240*192]);e.writeMemory(toAddr(0x58aaaa),new byte[16384]);put(e,O+8,4,H);put(e,H+23,1,s&4);for(int i=0;i<4;i++)put(e,H+28+i,1,120+i);int x=346+s%9-4,y=420+s/9%9-4;put(e,P,2,x);put(e,P+2,2,y);for(int i=0;i<4;i++)put(e,P+20+i,1,240+i);int ax=(x+7)&65520,ay=(y+7)&65520,cell=ay*8+((short)(x+7)>>4);for(int i=0;i<4;i++)put(e,0x58aaaa+cell+(i&1)+(i>>1)*128,1,codes[(s+i*3)%codes.length]|(s&128));put(e,U+44,2,ax+delta[s%delta.length]);put(e,U+46,2,ay+delta[s/11%delta.length]);put(e,U+48,1,s%39);put(e,U+49,1,(s&1)*4);put(e,U+53,1,(s&2)!=0?18:0);put(e,0x4d02a2,1,0);execute(e);byte[]b=new byte[4];for(int i=0;i<4;i++)b[i]=(byte)read(e,0x58aaaa+cell+(i&1)+(i>>1)*128,1);out.println("{\"scenario\":"+s+",\"objectHash\":"+hash(e.readMemory(toAddr(P),44))+",\"terrainHash\":"+hash(b)+",\"events\":"+events+",\"eventHash\":"+(eh&0xffffffffL)+",\"allObjects\":"+read(e,0x4d02a2,1)+"}");}}finally{e.dispose();}}}
}
